<article class="mapr-card"><a class="mapr-card__image" href="<?php echo esc_url($product->url); ?>"><?php echo wp_kses_post($product->image); ?></a><div class="mapr-card__body"><?php if($product->family): ?><span class="mapr-card__family"><?php echo esc_html($product->family); ?></span><?php endif; ?><h2><a href="<?php echo esc_url($product->url); ?>"><?php echo esc_html($product->title); ?></a></h2><?php if($product->warning): ?><div class="mapr-warning"><strong>Controleer je product-/servicenummer</strong><span><?php echo esc_html(sprintf('Dit onderdeel past alleen op bepaalde uitvoeringen van %s %s.',$view->model['brand'],$view->model['commercial_type'])); ?></span></div><?php endif; ?><div class="mapr-stock"><?php echo wp_kses_post($product->stock_html); ?></div><div class="mapr-price"><?php echo wp_kses_post($product->price_html); ?></div><?php if($product->purchasable): ?><a class="mapr-cta" href="<?php echo esc_url($product->add_url); ?>" rel="nofollow"><?php echo esc_html($product->add_text); ?></a><?php else: ?><a class="mapr-cta mapr-cta--secondary" href="<?php echo esc_url($product->url); ?>">Bekijk product</a><?php endif; ?></div></article>
